test('addLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const original = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(invoice, original);
});

test('removeLine removes a line from an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const r = removeLine(invoice, 'DEV-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine returns LINE_NOT_FOUND for missing SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(removeLine(invoiceResult.value, 'INVALID-SKU'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine returns NO_LINES if removing last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(removeLine(invoiceResult.value, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = { ...invoiceResult.value, status: 'sent' };

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine returns NOT_DRAFT for null invoice', () => {
  assert.deepEqual(removeLine(null, 'DEV-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const original = JSON.parse(JSON.stringify(invoice));

  removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(invoice, original);
});

test('addLine and removeLine can be chained', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const add1 = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(add1.ok, true);

  const add2 = addLine(add1.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(add2.ok, true);

  const remove = removeLine(add2.value, 'LOGO-PACK');
  assert.equal(remove.ok, true);
  assert.equal(remove.value.lines.length, 2);
  assert.equal(remove.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(remove.value.lines[1].sku, 'COPY-HOUR');
});

test('totals update correctly after adding a line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);
  assert.equal(totals1.ok, true);
  const initial = totals1.value.subtotal;

  const addResult = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1 });
  const totals2 = invoiceTotals(addResult.value);
  assert.equal(totals2.ok, true);
  assert.equal(totals2.value.subtotal, initial + 120000);
});

